solution:
def invoice(items, gst=18):
    subtotal = sum(price * qty for name, price, qty in items)
    return round(subtotal * (100 + gst) / 100, 2)

alt:
def invoice(items, gst=18):
    subtotal = 0
    for name, price, qty in items:
        subtotal += price * qty
    return round(subtotal * (1 + gst / 100), 2)
